import sys,numpy as np
from PIL import Image
from scipy.ndimage import distance_transform_edt
sys.path.insert(0,'/app/output');import gen
T=np.array(Image.open('/app/target.png').convert('L'))<100;D=distance_transform_edt(~T)*.22186
for n in [11]:
 p=gen.STROKES[n][0][1];pts=[]
 for a,b in zip(p,p[1:]):
  for f in np.linspace(0,1,100):pts.append(np.array(a)*(1-f)+np.array(b)*f)
 bad=[]
 for u,v,z in pts:
  d=D[round(v),round(u)]
  if d>1:bad.append((round(u),round(v),round(d,1)))
 print(n,'points',len(pts),'bad',len(bad),'examples',bad[::max(1,len(bad)//20)][:20])
PY
